con:config.script:
import org.codehaus.groovy.runtime.TimeCategory
def now = new Date();
day = String.format('%tY-%<tm-%<td', now);
time = String.format('%tH:%<tM:%<tS', now);
def sendersTime = day + "T" + time;

// set property
def targetStep = testRunner.testCase.getTestStepByName("CreateCustomerOrderTest properties");
targetStep.setPropertyValue("header.sendersTime", sendersTime);

use (TimeCategory) {
//set delivery to date to the next day (otherwise validation failure)
	targetStep.setPropertyValue("order.earliestDeliveryTime",(String.format('%tY-%<tm-%<td',  new Date() + 1.hours) + "T" + String.format('%tH:%<tM:%<tS',new Date() + 1.hours)));
	targetStep.setPropertyValue("order.plannedDeliveryTime",(String.format('%tY-%<tm-%<td',  new Date() + 3.hours) + "T" + String.format('%tH:%<tM:%<tS',new Date() + 3.hours)));
	targetStep.setPropertyValue("order.latestDeliveryTime",(String.format('%tY-%<tm-%<td',  now + 4.hours) + "T" + String.format('%tH:%<tM:%<tS',new Date() + 4.hours)));
}

