	throw new Exception( "wrong object_label" );
}

def properties = testRunner.testCase.getTestStepByName("Properties")
def next_id = properties.getProperty("rfidTagNEW_ID")
inc(next_id);

// increment id
public inc(prop){
	def c = Integer.parseInt(prop.getValue())
	c = c + 1
	prop.setValue(c.toString())

}

//save file
def storeStep = testRunner.testCase.getTestStepByName( "Properties" );
storeStep.saveProperties();

