con:config.script:
//log.info("arriving waiting")
	Properties props = new java.util.Properties();

	/*
	//setting a common flag to report to other test-cases
	String testcase_name = "CommonPropertyholder"
	String suite_name = "PDA-initiated-HelperSuite"
	// init context
	//project = context.getMockRunner().getMockService().getProject(
	project = context.getCurrentStep().getTestCase().getTestSuite().getProject()

	testSuite = project.getTestSuiteByName(suite_name);
	testCase = testSuite.getTestCaseByName(testcase_name);
	testCase_properties = testCase.getTestStepByName("Properties")
	*/

	def verladeauftrag_arrived = false

// check if time is set
startTime = context.getProperty( "startTime" )
if( startTime == null )
{
   //emptying props
   props.store(new FileOutputStream("../logon-simulator/etc/soapui/dataexchange.properties"), null);
   log.info("emptying dataexchange props file and setting start time to" + startTime)

   startTime = System.currentTimeMillis()
   context.setProperty( "startTime", startTime )
}
timePassed = System.currentTimeMillis() - startTime
if( timePassed < 600000 )
{
	//log.info("time elasped:" + timePassed)

	props.load( new java.io.FileInputStream( "../logon-simulator/etc/soapui/dataexchange.properties" ));

	def actualvalue = props.getProperty("verladeauftrag_flag")
	//log.info("actual value is : " + actualvalue)
	if(actualvalue == "true") {
		verladeauftrag_arrived = true
	}

	//log.info("verladeauftrag_arrived value is : " + verladeauftrag_arrived)

	//log.info("waiting...")
	if (verladeauftrag_arrived) {
		log.info("-----------verladeauftrag arrived-----------")
		props.store(new FileOutputStream("../logon-simulator/etc/soapui/dataexchange.properties"), null);
		context.setProperty( "startTime", null )
		testRunner.gotoStep( 1 )
	}
	else {
		// countdown and set name
		//log.info("waitingLKWVerladeAuftragNeu - " + (60000-timePassed) + "ms left")
		//log.info "timePassed = " + timePassed
		Thread.sleep( 1000 )
		testRunner.gotoStep( 0 )
	}
}
else
{
   context.setProperty( "startTime", null )
   log.info "timePassed = " + timePassed + ", exiting.."
   testRunner.gotoStepByName("error")
}

