log.info("++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++waitForTourDataAndSetProperties: incoming request arrived --")

// set up
String error_step = "error"

def runner = context.getTestRunner()
def groovyUtils = new com.eviware.soapui.support.GroovyUtils(context);
def holder = groovyUtils.getXmlHolder(mockRequest.requestContent);

log.info("-------------------------------------------------")
log.info(holder.getPrettyXml())
log.info("-------------------------------------------------")

if(holder.getNodeValue("//*:LOGONEvent[*:eventName='loadOrder']/*:eventID") != null) {

	log.info("--waitForTourDataAndSetProperties: incoming request contains loadOrder event --")


def properties = runner.testCase.getTestStepByName("Properties")
def storeProperties = runner.testCase.getTestStepByName("Store Properties")

def requestID = holder.getNodeValue("//*:sessionID")
log.info("sessionID: " + requestID)

log.info("----START-----Loading properties from request---------")
def assignmentID = holder.getNodeValue("//*:LOGONEventLOGONDataField[*:name='assignmentID']/*:value");
log.info("assignment id : " + assignmentID)
properties.setPropertyValue("curr_logonAssignmentID", assignmentID)

def loadAssignmentPartID = holder.getNodeValue("//*:LOGONEvent[*:eventName='loadOrder']/*:LOGONData/*:Field/*:LOGONEventLOGONDataField[*:name='assignmentPartID']/*:value");
log.info("loadAssignmentPartID id : " + loadAssignmentPartID)
properties.setPropertyValue("curr_logonAssignmentPartID", loadAssignmentPartID)
properties.setPropertyValue("loadAssignmentPartID", loadAssignmentPartID)

def logonOrderNumber = holder.getNodeValue("//*:LOGONEvent[*:eventName='unloadOrder']/*:LOGONData/*:Field/*:LOGONEventLOGONDataField[*:name='orderNumber']/*:value");
log.info("logonOrderNumber : " + logonOrderNumber)
storeProperties.setPropertyValue("logon_nr", logonOrderNumber)

def shiptoID = holder.getNodeValue("//*:LOGONEvent[*:eventName='unloadOrder']/*:LOGONData/*:Field/*:LOGONEventLOGONDataField[*:name='shipToID']/*:value");
log.info("curr_shipToID : " + shiptoID)
properties.setPropertyValue("curr_shipToID", shiptoID)

def unloadAssignmentPartID = holder.getNodeValue("//*:LOGONEvent[*:eventName='unloadOrder']/*:LOGONData/*:Field/*:LOGONEventLOGONDataField[*:name='assignmentPartID']/*:value");
log.info("unloadAssignmentPartID : " + unloadAssignmentPartID)
properties.setPropertyValue("unloadAssignmentPartID", unloadAssignmentPartID)

//shippingpointID
def shippingpointID = holder.getNodeValue("//*:LOGONEvent[*:eventName='loadOrder']/*:LOGONData/*:Field/*:LOGONEventLOGONDataField[*:name='shippingpointID']/*:value");
log.info("shippingpointID : " + shippingpointID)
properties.setPropertyValue("shippingpointID", shippingpointID)

//loadingpoint -> rfidIdentity , rfidLabel, loadingPointID (objectID)
def terminalRFID = holder.getNodeValue("//*:LOGONEvent[*:eventName='loadOrder']/*:LOGONData/*:loadingPoint/*:loadingPointDataField/*:rfidObject/*:rfidTag/*:rfid/*:rfidIdentity");
log.info("terminalRFID : " + terminalRFID)
properties.setPropertyValue("terminalRFID", terminalRFID)

def terminalLabel  = holder.getNodeValue("//*:LOGONEvent[*:eventName='loadOrder']/*:LOGONData/*:loadingPoint/*:loadingPointDataField/*:rfidObject/*:rfidTag/*:rfid/*:rfidLabel");
log.info("terminalLabel : " + terminalLabel)
properties.setPropertyValue("terminalLabel", terminalLabel)

def loadingPointID  = holder.getNodeValue("//*:LOGONEvent[*:eventName='loadOrder']/*:LOGONData/*:loadingPoint/*:loadingPointDataField/*:rfidObject/*:objectID");
log.info("loadingPointID : " + loadingPointID)
properties.setPropertyValue("loadingPointID", loadingPointID)

//shippingpointCoordLat, shippingpointCoordLon
def shippingpointCoordLat = holder.getNodeValue("//*:LOGONEvent[*:eventName='loadOrder']/*:LOGONData/*:Field/*:LOGONEventLOGONDataField[*:name='shippingpointCoordLat']/*:value");
log.info("shippingpointCoordLat : " + shippingpointCoordLat)
properties.setPropertyValue("shippingpointCoordLat", shippingpointCoordLat)

def shippingpointCoordLon = holder.getNodeValue("//*:LOGONEvent[*:eventName='loadOrder']/*:LOGONData/*:Field/*:LOGONEventLOGONDataField[*:name='shippingpointCoordLon']/*:value");
log.info("shippingpointCoordLon : " + shippingpointCoordLon)
properties.setPropertyValue("shippingpointCoordLon", shippingpointCoordLon)

//siloLabel_01 = rfid objectlabel of the shipto_silo_id in order_item
//siloRFIDIdentity_01 = rfid identity of the shipto_silo_id in order_item
def siloRFID  = holder.getNodeValue("//*:LOGONEvent[*:eventName='unloadOrder']/*:LOGONData/*:unloadOrderItem/*:unloadOrderItemDataField/*:rfidObject/*:rfidObjectDataField[*:name='shipToSiloList']/*:value/*:rfidObject[1]/*:rfidTag/*:rfid[1]/*:rfidIdentity");
log.info("siloRFID : " + siloRFID)
properties.setPropertyValue("siloRFIDIdentity_01", siloRFID)

def siloLabel  = holder.getNodeValue("//*:LOGONEvent[*:eventName='unloadOrder']/*:LOGONData/*:unloadOrderItem/*:unloadOrderItemDataField/*:rfidObject/*:rfidObjectDataField/*:value/*:rfidObject/*:rfidTag/*:rfid/*:rfidLabel");
log.info("siloLabel : " + siloLabel)
properties.setPropertyValue("siloLabel_01", siloLabel)

//unloadOrderItemID (order_item_id of order_item, especially needed in case of tour)
def unloadOrderItemID = holder.getNodeValue("//*:LOGONEvent[*:eventName='unloadOrder']/*:LOGONData/*:unloadOrderItem/*:unloadOrderItemDataField/*:Field/*:LOGONEventLOGONDataField[*:name='unloadOrderItemID']/*:value");
log.info("unloadOrderItemID : " + unloadOrderItemID)
properties.setPropertyValue("unloadOrderItemID", unloadOrderItemID)

def enterEndpointAssPartId  = holder.getNodeValue("//*:LOGONEvent[*:eventName='postOrder']/*:LOGONData/*:Field/*:LOGONEventLOGONDataField[*:name='assignmentPartID']/*:value");
log.info("enterEndpointAssPartId : " + enterEndpointAssPartId)
properties.setPropertyValue("enterEndpointAssPartId", enterEndpointAssPartId)


log.info("----END-----Loading properties from request---------")
}

