log.info("--- error: testcase orderDataWithParallel failed")
// fehler
produceError()

Properties props = new java.util.Properties();
   def pathPropertiesStep = testRunner.testCase.getTestStepByName( "Test Path Properties" );
   def common_path= pathPropertiesStep.getProperty("common_path").getValue()
   def dataexchange_path= pathPropertiesStep.getProperty("dataexchange_path").getValue()
   log.info("--------------data exchange path : " + dataexchange_path + "----------------------");
   log.info("-------------- common_path : " +  common_path + "----------------------");

	def transmitted = false

// check if time is set
startTime = context.getProperty( "startTime" )
if( startTime == null )
{
   props.store(new FileOutputStream(dataexchange_path), null);
   log.info("emptying dataexchange props file and setting start time to" + startTime)

   startTime = System.currentTimeMillis()
   context.setProperty( "startTime", startTime )
}
timePassed = System.currentTimeMillis() - startTime
if( timePassed < 60000 )
{
	props.load( new java.io.FileInputStream( common_path ));

	def actualvalue = props.getProperty("transmitted")

	if(actualvalue == "true") {
		transmitted = true
	}

	if (transmitted) {
		log.info("-----------transmission happened-----------")
		props.store(new FileOutputStream(dataexchange_path), null);
		context.setProperty( "startTime", null )
		testRunner.gotoStepByName("Load Testdata Properties")
	}
	else {
		Thread.sleep( 1000 )
		testRunner.gotoStepByName("Check If Order Transmitted")
	}
}
else
{
   context.setProperty( "startTime", null )
   log.info "timePassed = " + timePassed + ", exiting.."
   testRunner.gotoStepByName("error")
}

// read the file
def properties = new java.util.Properties();
