while (iter.hasNext()) {
	def name = iter.next();

	if (	targetStep.hasProperty(name)){
		targetStep.setPropertyValue(name, properties.getProperty(name));
		log.info("Properties has property " + name.toUpperCase());
	}
	if (	targetStep2.hasProperty(name)){
		targetStep2.setPropertyValue(name, properties.getProperty(name));
		log.info("Store Properties has property " + name.toUpperCase());
	}
}

