def properties = runner.testCase.getTestStepByName("Properties")

def i=2;

def unloadOrderItemNth = properties.getPropertyValue("unloadOrderItemID" + i);
while (unloadOrderItemNth != null ) {
	log.info("Found multiple unloadOrderItemIDs for the current unload assignment part, going back and running again startUnLoad and endUnLoad");
	properties.setPropertyValue("unloadOrderItemID", unloadOrderItemNth)
	log.info("unloadOrderItemID=" + unloadOrderItemNth);
	runner.runTestStepByName("startUnLoad");
	runner.runTestStepByName("Delay 1");
	runner.runTestStepByName("endUnLoad");
	i++;
	unloadOrderItemNth = properties.getPropertyValue("unloadOrderItemID" + i);
}

