final String dirName = "build/test/lib/individual"
final String fileName = "mop.properties"

def dir = new File(dirName)
def file = new File(dir, fileName)

if (file.exists()) {
	file.delete()
	log.info("MOP.PROPERTIES FILE EXISTS, DELETING")
}
else {
	log.info("NO MOP.PROPERTIES FILE EXISTS")
}

def properties = new java.util.Properties();
properties.load( new java.io.FileInputStream( "build/test/lib/CEM_workflow_dataexchange.properties" ));
def targetStep = testRunner.testCase.getTestStepByName( "loadOrderNotification properties" );

// assign all properties
def names = new java.util.TreeSet(properties.stringPropertyNames()).iterator();
while (names.hasNext()) {
	def name = names.next();
	def value = properties.getProperty(name)
	def trimmedName = trimLoadOrderNotificationPrefix(name)
	log.info(trimmedName + "=" + value);
	targetStep.setPropertyValue(trimmedName, value);
}

def now = new Date();

day = String.format('%tY-%<tm-%<td', now);
time = String.format('%tH:%<tM:%<tS', now);
def sendersTime = day + "T" + time;

targetStep.setPropertyValue("header.sendersTime", sendersTime);

def trimLoadOrderNotificationPrefix(name) {
	def trimmedName = name.replaceAll("\\.loadOrderNotificationRequest\\.","")
	trimmedName = trimmedName.replaceAll("loadOrder\\.","")
}

// read the file
def properties = new java.util.Properties();
properties.load( new java.io.FileInputStream( "etc/soapui/testdata.properties" ));
def targetStep = testRunner.testCase.getTestStepByName( "Properties" );
def targetStep2 = testRunner.testCase.getTestStepByName( "Store Properties" );

// assign all properties
def names = new java.util.TreeSet(properties.stringPropertyNames()).iterator();
while (names.hasNext()) {
	def name = names.next();
	targetStep.setPropertyValue(name, properties.getProperty(name));
	targetStep2.setPropertyValue(name, properties.getProperty(name));
}

def properties = testRunner.testCase.getTestStepByName( "loadOrderNotification properties" );
log.info (properties);
def truckId = properties.getPropertyValue("vehicle.truckId");
def truckLabel = properties.getPropertyValue("vehicle.truckPlateNo");

log.info("Setting truck id to " + truckId + " and truckLabel " + truckLabel);

def targetStep = testRunner.testCase.getTestStepByName( "Properties" );
def targetStep2 = testRunner.testCase.getTestStepByName( "Store Properties" );

// assign all properties
def names =properties.getPropertyNames().iterator();
while (names.hasNext()) {
	def name = names.next();
	targetStep.setPropertyValue(name, properties.getPropertyValue(name));
	targetStep2.setPropertyValue(name, properties.getPropertyValue(name));
}

targetStep.setPropertyValue("truckId", truckId);
targetStep2.setPropertyValue("truckLabel", truckLabel);

def today = new Date();
def formatedDay = String.format('%tY-%<tm-%<td', today);
def formatedTime = String.format('%tH:%<tM:%<tS', today);
def formatedToday = formatedDay + "T" + formatedTime;
def sendersTime = "sendersTime";
def geoTime = "geoTime";

// set property
def targetStep = testRunner.testCase.getTestStepByName( "Properties" );
def storeStep = testRunner.testCase.getTestStepByName( "Store Properties" );
targetStep.setPropertyValue( sendersTime, formatedToday);
targetStep.setPropertyValue( geoTime, formatedToday);
storeStep.setPropertyValue( sendersTime, formatedToday);
storeStep.setPropertyValue( geoTime, formatedToday);

//save file
def storeStep = testRunner.testCase.getTestStepByName( "Store Properties" );
storeStep.saveProperties();

final String dirName = "build/test/lib/individual"
final String fileName = "mop.properties"

def runner = context.getTestRunner()
def _properties = new java.util.Properties()
def ready = false

startTime = System.currentTimeMillis()
while (!ready && System.currentTimeMillis() - startTime < 300000) {
    _properties.load(new java.io.FileInputStream("$dirName/$fileName"))
    ready = _properties.getProperty("loadOrder.eventName")

    if (!ready)
        Thread.sleep(1000)
}

//context.mopMockRunner.stop()

if (!ready)
    runner.fail("CEM Test Suite / Standard Bulk CEM workflow / after : readyForOperation not received within time!")

def properties = runner.testCase.getTestStepByName("Properties")
def storeProperties = runner.testCase.getTestStepByName("Store Properties")

def sessionId = _properties.getProperty("sessionID")
log.info("session id : $sessionId")
properties.setPropertyValue("curr_sessionID", sessionId)

def assignmentId = _properties.getProperty("loadOrder.assignmentID")
log.info("assignment id : $assignmentId")
properties.setPropertyValue("curr_logonAssignmentID", assignmentId)

def loadAssignmentPartId = _properties.getProperty("loadOrder.assignmentPartID");
log.info("loadAssignmentPart id : $loadAssignmentPartId")
properties.setPropertyValue("curr_logonAssignmentPartID", loadAssignmentPartId)
properties.setPropertyValue("loadAssignmentPartID", loadAssignmentPartId)

def logonOrderNumber = _properties.getProperty("unloadOrder.orderNumber");
log.info("logonOrderNumber : $logonOrderNumber")
storeProperties.setPropertyValue("logon_nr", logonOrderNumber)

def shiptoId = _properties.getProperty("unloadOrder.shipToID");
log.info("curr_shipToID : $shiptoId")
properties.setPropertyValue("curr_shipToID", shiptoId)

def unloadAssignmentPartId = _properties.getProperty("unloadOrder.assignmentPartID");
log.info("unloadAssignmentPartID : $unloadAssignmentPartId")
properties.setPropertyValue("unloadAssignmentPartID", unloadAssignmentPartId)

def shippingpointId = _properties.getProperty("loadOrder.shippingpointID");
log.info("shippingpointID : $shippingpointId")
properties.setPropertyValue("shippingpointID", shippingpointId)

//loadingpoint -> rfidIdentity , rfidLabel, loadingPointID (objectID)
def terminalRfid = _properties.getProperty("loadOrder.lp.1.rfid.rfidTag.1.rfidIdentity")
log.info("terminalRFID : " + terminalRfid)
properties.setPropertyValue("terminalRFID", terminalRfid)

def terminalLabel  = _properties.getProperty("loadOrder.lp.1.rfid.rfidTag.1.rfidLabel");
log.info("terminalLabel : " + terminalLabel)
properties.setPropertyValue("terminalLabel", terminalLabel)

def loadingPointId  = _properties.getProperty("loadOrder.lp.1.rfid.objectID");
log.info("loadingPointID : " + loadingPointId)
properties.setPropertyValue("loadingPointID", loadingPointId)

def shippingpointCoordLat = _properties.getProperty("loadOrder.shippingpointCoordLat");
log.info("shippingpointCoordLat : $shippingpointCoordLat")
properties.setPropertyValue("shippingpointCoordLat", shippingpointCoordLat)

def shippingpointCoordLon = _properties.getProperty("loadOrder.shippingpointCoordLon");
log.info("shippingpointCoordLon : $shippingpointCoordLon")
properties.setPropertyValue("shippingpointCoordLon", shippingpointCoordLon)

//siloLabel_01 = rfid objectlabel of the shipto_silo_id in order_item
//siloRFIDIdentity_01 = rfid identity of the shipto_silo_id in order_item
def siloRfid  = _properties.getProperty("unloadOrder.oi.1.rfid.shipToSiloList.rfidObject.1.rfidTag.1.rfidIdentity")
log.info("siloRFID : " + siloRfid)
properties.setPropertyValue("siloRFIDIdentity_01", siloRfid)

def siloLabel  = _properties.getProperty("unloadOrder.oi.1.rfid.shipToSiloList.rfidObject.1.rfidTag.1.rfidLabel");
log.info("siloLabel : " + siloLabel)
properties.setPropertyValue("siloLabel_01", siloLabel)

def unloadOrderItemId = _properties.getProperty("unloadOrder.oi.1.unloadOrderItemID");
log.info("unloadOrderItemID : " + unloadOrderItemId)
properties.setPropertyValue("unloadOrderItemID", unloadOrderItemId)

def enterEndpointAssPartId  = _properties.getProperty("postOrder.assignmentPartID");
log.info("enterEndpointAssPartId : $enterEndpointAssPartId")
properties.setPropertyValue("enterEndpointAssPartId", enterEndpointAssPartId)

storeProperties.saveProperties()

