//siloLabel_01 = rfid objectlabel of the shipto_silo_id in order_item
//siloRFIDIdentity_01 = rfid identity of the shipto_silo_id in order_item
def siloRfid  = _properties.getProperty("unloadOrder.oi.1.rfid.shipToSiloList.rfidObject.1.rfidTag.1.rfidIdentity")
