log.info("loadOrderNotificationRequest")

// xml holder
def groovyUtils = new com.eviware.soapui.support.GroovyUtils(context)
def holder = groovyUtils.getXmlHolder(mockRequest.requestContent)

// read values
def loadOrderId = holder.getNodeValue("//*:loadOrderId")

def Properties receivedProperties = new java.util.Properties();

log.info("loadOrderNotificationRequest arrived with loadOrderId: " + loadOrderId)

// check values (first three for nightly build)
if (loadOrderId == '100') {
	return "TechnicalError"
}
else {
	try {
	// read all values from XML and transfer to properties
	String path = "//*:loadOrderNotificationRequest"
	nodes = holder.getDomNodes("//*:loadOrderNotificationRequest/*")
	nodeHasChild = false;
	for (node in nodes) {
		nodeHasChild = true;
		name = node.getNodeName()
		nameLevel1="";
		nameLevel2="";
		nameLevel3="";
		nameLevel4="";

		value = holder.getNodeValue("//*:loadOrderNotificationRequest/" + name)

		node1HasChild=false;
		nodesLevel1 = holder.getDomNodes("//*:loadOrderNotificationRequest/*:"+ name + "/*")
		for (nodeLevel1 in nodesLevel1) {
			node1HasChild = true;
			nameLevel1 = nodeLevel1.getNodeName()
			nameLevel2="";
			nameLevel3="";
			nameLevel4="";

			valueLevel1 = holder.getNodeValue("//*:loadOrderNotificationRequest/*:"+ name + "/*:" + nameLevel1)

			node2HasChild = false;
			nodesLevel2 = holder.getDomNodes("//*:loadOrderNotificationRequest/*:"+ name + "/*:" + nameLevel1 + "/*")
			for (nodeLevel2 in nodesLevel2) {
				node2HasChild = true;
				nameLevel2 = nodeLevel2.getNodeName()
				nameLevel3="";
				nameLevel4="";

				valueLevel2 = holder.getNodeValue("//*:loadOrderNotificationRequest/*:"+ name + "/*:" + nameLevel1 + "/*:" + nameLevel2)

				node3HasChild = false;
				nodesLevel3 = holder.getDomNodes("//*:loadOrderNotificationRequest/*:"+ name + "/*:" + nameLevel1 + "/*:" + nameLevel2 + "/*")
				for (nodeLevel3 in nodesLevel3) {
					node3HasChild = true;
					nameLevel3 = nodeLevel3.getNodeName()
					nameLevel4="";

					valueLevel3 = holder.getNodeValue("//*:loadOrderNotificationRequest/*:"+ name + "/*:" + nameLevel1 + "/*:" + nameLevel2 + "/*:" + nameLevel3)

					node4HasChild = false;
					nodesLevel4 = holder.getDomNodes("//*:loadOrderNotificationRequest/*:"+ name + "/*:" + nameLevel1 + "/*:" + nameLevel2 + "/*:" + nameLevel3 + "/*")
					for (nodeLevel4 in nodesLevel4) {
						node4HasChild = true;
						nameLevel4 = nodeLevel4.getNodeName()
						valueLevel4 = holder.getNodeValue("//*:loadOrderNotificationRequest/*:"+ name + "/*:" + nameLevel1 + "/*:" + nameLevel2 + "/*:" + nameLevel3 + "/*:" + nameLevel4)

						setPropertyAndLog (/*name + "." + */ nameLevel1 + "." + nameLevel2 + "." + nameLevel3 + "." + nameLevel4,  valueLevel4, receivedProperties)
					}
					if (node4HasChild == false) {
					 setPropertyAndLog (/*name + "." + */ nameLevel1 + "." + nameLevel2 + "." + nameLevel3, valueLevel3, receivedProperties)
					}
				}
				if (node3HasChild == false) {
					setPropertyAndLog( /*name + "." +*/ nameLevel1 + "." + nameLevel2  , valueLevel2, receivedProperties)
				}
			}
			if (node2HasChild == false) {
				setPropertyAndLog (/*name + "." + */ nameLevel1  , valueLevel1, receivedProperties)
			}
		}
		//level 1 attributes do not interest us
		/*if (node1HasChild == false) {

			setPropertyAndLog(name , value, receivedProperties);
		}*/

		mockOperation.getMockService().setPropertyValue(name, value)

		Properties props = new java.util.Properties();
		props.setProperty("notification_flag", "true");
		props.store(new FileOutputStream("../logon-simulator/etc/soapui/dataexchange.properties"), null);

	}
	}
	catch (Exception e) {
		log.info(e);
		log.info("-----------------------");
		log.info("name=" + name);
		log.info("nameLevel1=" + nameLevel1);
		log.info("nameLevel2=" + nameLevel2);
		log.info("nameLevel3=" + nameLevel3);
		log.info("nameLevel4=" + nameLevel4);
		log.info("-----------------------");
	}



	receivedProperties.store(new FileOutputStream("build/test/lib/CEM_workflow_dataexchange.properties"), null);
	return "NoError"
}
def setPropertyAndLog(key,value, receivedProperties) {
	log.info (key + "=" + ( value == null ? "" : value))
	receivedProperties.setProperty(key, value)
}

/*
This dispatcher script overwrites the values in the file build/test/lib/CEM_workflow_dataexchange.properties with the values
received in the request. Further on the received values can be loaded by different test steps.
*/


log.info("loadOrderNotificationRequest")

// xml holder
def groovyUtils = new com.eviware.soapui.support.GroovyUtils(context)
def holder = groovyUtils.getXmlHolder(mockRequest.requestContent)

// read values
def loadOrderId = holder.getNodeValue("//*:loadOrderId")

def Properties receivedProperties = new java.util.Properties();

log.info("loadOrderNotificationRequest arrived with loadOrderId: " + loadOrderId)

// check values (first three for nightly build)
if (loadOrderId == '100') {
    return "TechnicalError"
}
else {
    try {
    // read all values from XML and transfer to properties
    String path = "//*:loadOrderNotificationRequest"
    nodes = holder.getDomNodes("//*:loadOrderNotificationRequest/*")
    processLevel(nodes, path, holder,receivedProperties);
    }
    catch (Exception e) {
        log.info("Exception caught " + e);
    }

    receivedProperties.store(new FileOutputStream("build/test/lib/CEM_workflow_dataexchange.properties"), null);
    return "NoError"
}


def processLevel(nodes, path, holder, receivedProperties) {
    //log.info("processLevel" + path);
    def count = 1;
    for (node in nodes) {

        name = node.getNodeName()

        def countpath = path + "/*:" + name
        def seqCount = Integer.valueOf(holder["count(" + countpath + ")"]).intValue()
        def pathOfNode = (path + "/*:" + name + (seqCount == 1  ? "" : ("["+ count + "]")));
        def nodesOfNode = holder.getDomNodes(pathOfNode + "/*");
        def nodeLength =nodesOfNode.length

        if (nodeLength > 0 ) {

            processLevel(nodesOfNode, pathOfNode, holder, receivedProperties);

            count ++;
            if ( count > seqCount) {
                count = 1;
            }
        }
        else {
            value = holder.getNodeValue(path + "/" + name)
            def prefix = pathOfNode.replaceAll('/', "").replaceAll('\\*', "").replaceAll(':', ".");
            setPropertyAndLog(prefix, value, receivedProperties);
        }
    }
}
def setPropertyAndLog(key,value, receivedProperties) {
    def safevalue = value == null ? "" : value
    log.info ( key + "=" + (safevalue ))
    receivedProperties.setProperty( key, safevalue)
}

con:mockService.con:onRequestScript:
import groovy.util.XmlSlurper
import javax.xml.namespace.QName

def getChildrenStrValIfAvailable(psItem, childrenName, fallBackValue) {
    def childrenArray = psItem.selectChildren(new QName(childrenName))
    if (childrenArray == null || childrenArray.length == 0){
        return fallBackValue
    }
    def childrenItem = childrenArray[0]
    def childrenItemText = childrenItem.getStringValue()
    return childrenItemText
}

log.info('startOnRequest ===>')

def requestContentElement = mockRequest.getContentElement()
def psItems = requestContentElement.selectChildren(new QName('ZTSD_PS_ITEMS'))[0]
def psItemChildren = psItems.selectChildren(new QName('item'))

def myResponseText = ''
  myResponseText += '<soapenv:Envelope xmlns:soapenv="http://schemas.xmlsoap.org/soap/envelope/" xmlns:urn="urn:sap-com:document:sap:rfc:functions">'
  myResponseText += '<soapenv:Body>'
  myResponseText += '<urn:ZFSD_PRICE_SIMULATION.Response>'
  myResponseText += '<ZTSD_PS_ITEMS>'

  for ( psItem in psItemChildren ) {

    def itemNo 		= getChildrenStrValIfAvailable(psItem, 'ITM_NUMBER', null)
    def material 	= getChildrenStrValIfAvailable(psItem, 'MATERIAL', 'ADN000000001404878')
    def targetQty 	= getChildrenStrValIfAvailable(psItem, 'TARGET_QTY', 500)
    def targetQtyUom 	= getChildrenStrValIfAvailable(psItem, 'TARGET_QU', 'TO')
    def netValue 	= getChildrenStrValIfAvailable(psItem, 'NETWR', 1425)
    def vatValue 	= getChildrenStrValIfAvailable(psItem, 'MWSBP', 5.7)

    myResponseText += '<item>'
      myResponseText += '<ITM_NUMBER>'+itemNo+'</ITM_NUMBER>'
      myResponseText += '<MATERIAL>'+material+'</MATERIAL>'
      myResponseText += '<TARGET_QTY>'+targetQty+'</TARGET_QTY>'
      myResponseText += '<TARGET_QU>'+targetQtyUom+'</TARGET_QU>'
      myResponseText += '<NETWR>'+netValue+'</NETWR>'
      myResponseText += '<MWSBP>'+vatValue+'</MWSBP>'
      myResponseText += '<SUBTOTAL1>36.36</SUBTOTAL1>'
    myResponseText += '</item>'

  }

  myResponseText += '</ZTSD_PS_ITEMS>'
  myResponseText += '</urn:ZFSD_PRICE_SIMULATION.Response>'
  myResponseText += '</soapenv:Body>'
  myResponseText += '</soapenv:Envelope>'

mockRequest.httpResponse.status = 200
mockRequest.httpResponse.addHeader("Content-Type","text/plain");

mockRequest.httpResponse.writer.print(myResponseText);

log.info('stopOnRequest <===')

def myResponse = new com.eviware.soapui.impl.wsdl.mock.WsdlMockResult( mockRequest )

return myResponse

con:mockOperation.con:dispatchPath:
/*
This dispatcher script overwrites the values in the file build/test/lib/individual/mop/test.properties with the values
received in the request. Further on the received values can be loaded by different test steps.
*/

log.info("Processing MOP request ...")

// xml holder
def groovyUtils = new com.eviware.soapui.support.GroovyUtils(context)
def holder = groovyUtils.getXmlHolder(mockRequest.requestContent)

def Properties properties = new java.util.Properties();

final String dirName = "build/test/lib/individual"
final String fileName = "mop.properties"

def dir = new File(dirName)
def file = new File(dir, fileName)
if (file.exists())
     properties.load(new java.io.FileInputStream("$dirName/$fileName"))

try {
    // read all values from XML and transfer to properties
    final String rootPath = "//*:LOGONMessage"

    final String eventListSuffix = "logonEventList"
    final String eventListPath = "$rootPath/*:$eventListSuffix"

    final String eventNameSuffix = "eventName"

    final String lpFieldSuffix = "LOGONData/*:loadingPoint/*:loadingPointDataField/*:Field"
    final String lpRfidSuffix = "LOGONData/*:loadingPoint/*:loadingPointDataField/*:rfidObject"
    final String oiFieldSuffix = "LOGONData/*:unloadOrderItem/*:unloadOrderItemDataField/*:Field"
    final String oiRfidSuffix = "LOGONData/*:unloadOrderItem/*:unloadOrderItemDataField/*:rfidObject/*:rfidObjectDataField"

    // process root elements
    for (rootElem in holder.getDomNodes("$rootPath/*")) {
        def rootElemName = rootElem.getLocalName()
        if (rootElemName != eventListSuffix) {
            def rootElemValue = holder.getNodeValue("$rootPath/*:$rootElemName")
            setPropertyAndLog(rootElemName, rootElemValue, properties)
        }
    }

    // process event list
    def eventCount = 1
    for (event in holder.getDomNodes("$eventListPath/*")) {
    	   def eventNodeName = event.getLocalName()
    	   def eventPath = "$eventListPath/*:$eventNodeName[$eventCount]"

    	   // determine event name
    	   def eventName = holder.getNodeValue("$eventPath/*:$eventNameSuffix")

    	   // retrieve event fields
    	   for (eventElem in holder.getDomNodes("$eventPath/*")) {
    	       def eventElemName = eventElem.getLocalName()
    	       if (eventElemName != "LOGONData") {
    	           def eventElemValue = holder.getNodeValue("$eventPath/*:$eventElemName")
    	           setPropertyAndLog("$eventName.$eventElemName", eventElemValue, properties)
    	       }
    	   }

    	   // retrieve name/value pairs
    	   processNameValuePairs("$eventPath/*:LOGONData/*:Field", holder, "$eventName.", properties)

        // retrieve event-level rfid information
    	   processRfidObject("$eventPath/*:LOGONData/*:rfidObject", holder, "${eventName}.rfid.", properties)

    	   // retrieve unload order item information
    	   processUnloadOrderItems("$eventPath/*:LOGONData/*:unloadOrderItem", holder, "${eventName}.oi.", properties)

    	   // retrieve loading point information
    	   processLoadingPoints("$eventPath/*:LOGONData/*:loadingPoint", holder, "${eventName}.lp.", properties)

    	   eventCount++
    }
}
catch (Exception e) {
   log.info("Exception caught " + e);
}

properties.store(new FileOutputStream("$dirName/$fileName"), null);
return "NoError"

def processUnloadOrderItems(basePath, holder, keyPrefix, properties) {
    def count = 1
    for (oi in holder.getDomNodes("$basePath/*")) {
        def oiLocalName = oi.getLocalName()
        def oiPath = "$basePath/*:$oiLocalName[$count]"

    	   // retrieve name/value pairs
    	   processNameValuePairs("$oiPath/*:Field", holder, "${keyPrefix}${count}.", properties)

        // retrieve unload order item level rfid information
    	   processRfidObject("$oiPath/*:rfidObject", holder, "${keyPrefix}${count}.rfid.", properties)

        count++
    }
}

def processLoadingPoints(basePath, holder, keyPrefix, properties) {
    def count = 1
    for (lp in holder.getDomNodes("$basePath/*")) {
        def lpLocalName = lp.getLocalName()
        def lpPath = "$basePath/*:$lpLocalName[$count]"

    	   // retrieve name/value pairs
    	   processNameValuePairs("$lpPath/*:Field", holder, "${keyPrefix}${count}.", properties)

        // retrieve loading point level rfid information
    	   processInnerRfidObject("$lpPath/*:rfidObject", holder, "${keyPrefix}${count}.rfid.", properties)

        count++
    }
}

def processNameValuePairs(basePath, holder, keyPrefix, properties) {
    def count = 1
    for (pair in holder.getDomNodes("$basePath/*")) {
        def pairName = pair.getLocalName()
        def pairPath = "$basePath/*:$pairName[$count]"
        def key = holder.getNodeValue("$pairPath/*:name")
        def value = holder.getNodeValue("$pairPath/*:value")
        setPropertyAndLog("$keyPrefix$key", value, properties)
        count++
    }
}

def processRfidObject(basePath, holder, keyPrefix, properties) {
    def i = 1
    for (pair in holder.getDomNodes("$basePath/*")) {
        def pairName = pair.getLocalName()
        def pairPath = "$basePath/*:$pairName[$i]"
        def name = holder.getNodeValue("$pairPath/*:name")

        def j = 1
        for (object in holder.getDomNodes("$pairPath/*:value/*")) {
            def objectLocalName = object.getLocalName()
            def objectPath = "$pairPath/*:value/*:$objectLocalName[$j]"
            processInnerRfidObject(objectPath, holder, "${keyPrefix}${name}.rfidObject.${j}.", properties)
            j++
        }
        i++
    }
}

def processInnerRfidObject(basePath, holder, keyPrefix, properties) {
    for (objectElem in holder.getDomNodes("$basePath/*")) {
        def elemName = objectElem.getLocalName()
        if (elemName != "rfidTag") {
             def elemValue = holder.getNodeValue("$basePath/*:$elemName")
             setPropertyAndLog("$keyPrefix$elemName", elemValue, properties)
        }
    }

    // process rfidTag
    def count = 1
    for (tag in holder.getDomNodes("$basePath/*:rfidTag/*")) {
        def tagLocalName = tag.getLocalName()
        def tagPath = "$basePath/*:rfidTag/*:$tagLocalName[$count]"
        for (tagElem in holder.getDomNodes("$tagPath/*")) {
            def tagElemName = tagElem.getLocalName()
            def tagElemValue = holder.getNodeValue("$tagPath/*:$tagElemName")
            setPropertyAndLog("${keyPrefix}rfidTag.${count}.$tagElemName", tagElemValue, properties)
        }
    }
}

def setPropertyAndLog(key, value, properties) {
    def safevalue = value == null ? "" : value
    log.info "$key=$safevalue"
    properties.setProperty(key, safevalue)
}

