}

properties.store(new FileOutputStream("$dirName/$fileName"), null);

con:response.con:script:
// --------------------------
// run MessageAck TestCase
// --------------------------
log.info("-- success.Ok_Message --")
// xml holder
def groovyUtils = new com.eviware.soapui.support.GroovyUtils(context)
def holder = groovyUtils.getXmlHolder(mockRequest.requestContent)
String messageID = holder.getNodeValue("//*:LOGONEvent.LOGONDataField[*:name='messageID']/*:value");
// setup
String testcase_name = "messageAck_Remote"
String suite_name = "LOGON-initiated"
// init context
project = context.getMockRunner().getMockService().getProject();
testSuite = project.getTestSuiteByName(suite_name);
testCase = testSuite.getTestCaseByName(testcase_name);
testCase_properties = testCase.getTestStepByName("Properties")

// ---------------------------------------------------------------------------
// property update from local file
// -----------------------------------
def properties = new java.util.Properties();
//IMPORTANT use path from where the ant executes the shell script
properties.load( new java.io.FileInputStream( "../logon-simulator/etc/soapui/testdata.properties" ));
def names = properties.propertyNames();
while (names.hasMoreElements()) {
   def name = names.nextElement();
   testCase_properties.setPropertyValue(name, properties.getProperty(name));
   //log.info (name + "->" + properties.getProperty(name))
}
log.info "Update done."
// ---------------------------------------------------------------------------
// transfer properties
testCase_properties.setPropertyValue("messageID", messageID)
log.info "messageID " + messageID
// ---------------------------------------------------------------------------
// save properties to file
testCase_properties.saveProperties();
// ---------------------------------------------------------------------------
// run test case
runner = testCase.run(new com.eviware.soapui.support.types.StringToObjectMap(), true)

log.info("-- success.Ok_orderDataParallel --")
// ------------------------------------------------
// run orderDataParalle9013_Remote_PART1 TestCase
// -------------------------------------------------
// xml holder
def groovyUtils = new com.eviware.soapui.support.GroovyUtils(context)
def holder = groovyUtils.getXmlHolder(mockRequest.requestContent)

// setup
String testcase_name = "orderDataWithParallel9013_Remote_PART1"
String suite_name = "LOGON-initiated"
// init context
project = context.getMockRunner().getMockService().getProject()
testSuite = project.getTestSuiteByName(suite_name);
testCase = testSuite.getTestCaseByName(testcase_name);
testCase_properties = testCase.getTestStepByName("Properties")
// ---------------------------------------------------------------------------
// property update from local file
// -----------------------------------
def properties = new java.util.Properties();
//IMPORTANT use path from where the ant executes the shell script
properties.load( new java.io.FileInputStream( "../logon-simulator/etc/soapui/testdata.properties" ));
def names = properties.propertyNames();
while (names.hasMoreElements()) {
   def name = names.nextElement();
   testCase_properties.setPropertyValue(name, properties.getProperty(name));
   //log.info (name + "->" + properties.getProperty(name))
}
log.info "Update done."
// ---------------------------------------------------------------------------
// retrieve properties and transfer them to target test case
def assID = holder.getNodeValue("//*:LOGONEvent.LOGONDataField[*:name='logonAssignmentID']/*:value");
testCase_properties.setPropertyValue("curr_logonAssignmentID", assID)
def sessionID = holder.getNodeValue("//*:sessionID")
testCase_properties.setPropertyValue("curr_sessionID", sessionID)
// save other fields to properties
def DataFields = ['shippingpointCoordLat','shippingpointCoordLon', 'shippingpointID', 'shipToID', 'shipToCoordLat', 'shipToCoordLon'] as String[]
for (field in DataFields){
	path = "//*:LOGONEvent.LOGONDataField[*:name='" + field + "']/*:value"
	temp = holder.getNodeValue(path)
	log.info(field + ": " + temp)
	testCase_properties.setPropertyValue(field, temp)
}
// loadingPointList properties for loginParallel
String terminalLabel = holder.getNodeValue("//*:LOGONEvent.rfidObjectDataField[*:name='loadingPointList']/*:value/*:rfidObject[1]/*:objectName");
String terminalRFID = holder.getNodeValue("//*:LOGONEvent.rfidObjectDataField[*:name='loadingPointList']/*:value/*:rfidObject[1]/*:rfidTag/*:rfid[1]/*:rfidIdentity");
testCase_properties.setPropertyValue("terminalLabel", terminalLabel)
testCase_properties.setPropertyValue("terminalRFID", terminalRFID)
log.info("terminalLabel, terminalRFID: " + terminalLabel + ", " + terminalRFID)
// shipTo Silo
String siloLabel_01 = holder.getNodeValue("//*:LOGONEvent.rfidObjectDataField[*:name='shipToSiloList']/*:value/*:rfidObject[1]/*:objectName");
String siloRFIDIdentity_01 = holder.getNodeValue("//*:LOGONEvent.rfidObjectDataField[*:name='shipToSiloList']/*:value/*:rfidObject[1]/*:rfidTag/*:rfid[1]/*:rfidIdentity");
testCase_properties.setPropertyValue("siloLabel_01", siloLabel_01)
testCase_properties.setPropertyValue("siloRFIDIdentity_01", siloRFIDIdentity_01)
log.info("siloLabel_01, siloRFIDIdentity_01: " + siloLabel_01 + ", " + siloRFIDIdentity_01)
// ---------------------------------------------------------------------------
// save properties to file
testCase_properties.saveProperties();
// ---------------------------------------------------------------------------
// run test case
runner = testCase.run(new com.eviware.soapui.support.types.StringToObjectMap(), true)

log.info("-- success.Ok_loadingEnded --")
// --------------------------
// run orderDataWithParallel9013_Remote_PART2
// --------------------------
// xml holder
def groovyUtils = new com.eviware.soapui.support.GroovyUtils(context)
def holder = groovyUtils.getXmlHolder(mockRequest.requestContent)

// setup
String refcase_name = "orderDataWithParallel9013_Remote_PART1"
String testcase_name = "orderDataWithParallel9013_Remote_PART2"
String suite_name = "LOGON-initiated"
// init context
project = context.getMockRunner().getMockService().getProject()
testSuite = project.getTestSuiteByName(suite_name)
refCase = testSuite.getTestCaseByName(refcase_name)
testCase = testSuite.getTestCaseByName(testcase_name)
refCase_properties = refCase.getTestStepByName("Properties")


//compare sessionID
def sessionID = holder.getNodeValue("//*:sessionID")
def wantedSessionID = refCase_properties.getPropertyValue("curr_sessionID");

log.info("received session, wanted session: " + sessionID + ", " + wantedSessionID)

// run test case
if (sessionID == wantedSessionID) {
	runner = testCase.run(new com.eviware.soapui.support.types.StringToObjectMap(), true) // objectMap, async
}else{
	throw new Exception( "after loadingEnded: wrong sessionID" );
}

